export type Move=[name:string,desc:string,base:number,scaling:Partial<Record<string,number>>];
export function moveTier(s:Game,jobIdx:number){const j=jobs[jobIdx];return Math.min(100,j.attrStep?(s.jobsRank?.[jobIdx]||0):(s.skills[j.skill]||0))}
export function moveUnlocked(s:Game,targetJob:number,idx:number){if(s.job===16){const lv=s.jobsRank?.[16]||0;return lv>=(idx+1)*10}const j=jobs[targetJob];if(j.attrStep)return (s.jobsRank?.[targetJob]||0)>=(idx+1)*10;return (s.jobsRank?.[targetJob]||0)>=idx+1}
export function movePower(s:Game,jobIdx:number,idx:number){const m=jobs[jobIdx].moves?.[idx];if(!m)return 0;const [,desc,base,sc]=m;const mult=1+attrNames.reduce((acc,a)=>acc+((sc?.[a]||0)*(attr(s,a)/100)),0);const w=gearByName(s.equip?.weapon||'');return Math.round(base*mult+(w?.atk||0))}
export function moveCost(jobIdx:number,base:number){const n=jobs[jobIdx].name;if(n==='法师'||n==='战地祭司')return {mana:Math.round(base*.38)};if(n==='圣骑士'||n==='魔剑士'||n==='宫廷医者'||n==='传奇者')return {stamina:Math.round(base*.26),mana:Math.round(base*.26)};if(n==='游侠')return {stamina:Math.round(base*.32),mana:Math.round(base*.15)};return {stamina:Math.round(base*.45)}}
