export const skillAttr:Record<string,[string,number][]>={
 '剑术':[['力量',1],['体质',.5]],'盾牌':[['体质',1],['力量',.5]],'弓术':[['感知',1],['敏捷',.5]],'骑术':[['敏捷',1],['体质',.5]],'潜行':[['敏捷',1],['感知',.5]],'锻造':[['力量',1],['体质',.5]],'炼金':[['智力',1]],'医术':[['智力',1],['感知',.5]],'识字':[['智力',1]],'贸易':[['魅力',1],['智力',.5]],'礼仪':[['魅力',1],['意志',.5]],'指挥':[['意志',1],['魅力',.5]],'生存':[['体质',1],['感知',.5]],'元素':[['智力',1],['意志',.5]],'治疗':[['魅力',1],['意志',.5]],'结界':[['意志',1],['智力',.5]],'占卜':[['智力',1],['感知',.5]]
};
export function skillAttrBonus(s:Game,key:string){let v=0;for(const sk of skillNames){const map=skillAttr[sk]||[];for(const [a,w] of map){if(a===key){const val=s.skills[sk]||0;v+=Math.floor(val/(w>=1?20:40));}}}return v}
export function jobAttrMapOf(s:Game,jobIdx:number){const j=jobs[jobIdx];const map:Record<string,number>={};const add=(m?:Partial<Record<string,number>>)=>{if(m)for(const[k,v]of Object.entries(m))map[k]=(map[k]||0)+(v??0)};if(j.attrStep){if(jobIdx===16){for(let q=8;q<=15;q++)add(jobs[q].attr)}else if(j.req)j.req.forEach(([id])=>add(jobs[id].attr));}add(j.attr);return map}
export function jobAttrMap(s:Game){return jobAttrMapOf(s,s.job)}
export function levelAttrBonusOf(s:Game,jobIdx:number,key:string){const lv=s.jobsRank?.[jobIdx]||0;const own=lv*(jobs[jobIdx].attrStep?.[key]||0);const inherited=jobIdx===16?jobs.slice(8,16).reduce((acc,jb,q)=>acc+((Math.min(s.jobsRank?.[8+q]||0,50)*(jb.attrStep?.[key]||0))),0):0;return own+inherited}
export function levelAttrBonus(s:Game,key:string){return levelAttrBonusOf(s,s.job,key)}
export function expNeed(s:Game,jobIdx:number){const j=jobs[jobIdx];if(!j.attrStep)return 0;const lv=s.jobsRank?.[jobIdx]||0;const c=jobIdx===16?10:(jobIdx===9?5:jobIdx===14?4:jobIdx===8||jobIdx===11?4:3);return 100+lv*c}
export function expGain(s:Game){const j=jobs[s.job];return Math.round(40+(s.skills[j.skill]||0)*0.6)}
export function gearAttr(s:Game){const map:Record<string,number>={};for(const slot of ['weapon','armor','trinket'] as const){const g=gearByName(s.equip?.[slot]||'');if(g?.attr)for(const[k,v]of Object.entries(g.attr))map[k]=(map[k]||0)+(v||0)}return map}
export function attr(s:Game,key:string){const base=(s.attributes[key]||0)+(jobAttrMap(s)[key]||0)+skillAttrBonus(s,key)+levelAttrBonus(s,key)+(gearAttr(s)[key]||0);const pct=1+(jobs[s.job]?.passive?.attrPct||0)/100;return Math.max(0,Math.round(base*pct*10)/10)}
export function playerAtk(s:Game){const w=gearByName(s.equip?.weapon||'');return Math.max(1,Math.round(attr(s,'力量')*2+attr(s,'敏捷')*.5+(w?.atk||0)))}
export function playerDef(s:Game){const a=gearByName(s.equip?.armor||'');return Math.max(0,Math.round(attr(s,'体质')*.5+(a?.def||0)))}
export function maxHp(s:Game){const a=gearByName(s.equip?.armor||'');const t=gearByName(s.equip?.trinket||'');return Math.round(100+(attr(s,'体质')-10)*6+(a?.hp||0)+(t?.hp||0))}
export function maxStamina(s:Game){return Math.round(100+(attr(s,'体质')-10)*3+(attr(s,'力量')-10)*1.5)}
export function maxSpirit(s:Game){return Math.round(100+(attr(s,'意志')-10)*3+(attr(s,'魅力')-10))}
export function effectiveMaxMana(s:Game){return Math.round(Math.max(0,(s.maxMana||0)+(attr(s,'智力')-10)+(attr(s,'感知')-10)*.5+(jobs[s.job]?.passive?.mana||0)))}
export function checkUnlocks(s:Game){const unlocked:string[]=[];jobs.forEach((jb,i)=>{if(!jb.hidden||(s.jobsRank?.[i]||0)>0)return;const baseOk=i===16?jobs.slice(8,16).every((_,q)=>((s.jobsRank?.[8+q]||0)>=50)):(jb.req?jb.req.every(([id,r])=>s.jobsRank![id]>=r):false);const skillOk=!jb.skillReq||jb.skillReq.every(([sk,n])=>s.skills[sk]>=n);const attrOk=!jb.attrReq||jb.attrReq.every(([a,n])=>attr(s,a)>=n);if(baseOk&&skillOk&&attrOk){s.jobsRank![i]=1;unlocked.push(jb.name)}});return unlocked}
