export function rollDrop(s:Game,dg:Dungeon){if(rand(s)<.3){const tier=dg.tier;const potions=tier<=2?['黑面包','止血草','魔力药水','疗伤绷带','蜂蜜酒']:tier<=4?['生命药水','大瓶魔力药水','精力药剂','疗伤绷带']:tier<=6?['强效生命药水','强效魔力药水','强效精力药剂','高级疗伤绷带','圣水']:tier<=8?['巨龙之血','凤凰精华','圣水','强效生命药水']:['生命之泉圣水','贤者药剂','全能圣水'];return potions[Math.floor(rand(s)*potions.length)]}const qlo=dg.tier<=2?1:dg.tier<=4?2:dg.tier<=6?3:dg.tier<=8?4:dg.tier===9?5:6;const qhi=Math.min(7,qlo+1);let pool=gearShop.filter(g=>{const q=gearQuality(g.price);return q>=qlo&&q<=qhi});if(!pool.length)pool=gearShop.filter(g=>gearQuality(g.price)>=qlo);if(!pool.length)pool=gearShop.filter(g=>gearQuality(g.price)<=qhi);if(!pool.length)pool=gearShop.slice();return pool[Math.floor(rand(s)*pool.length)].name}
export type Gear={name:string,slot:'武器'|'护甲'|'饰品',atk?:number,def?:number,hp?:number,attr?:Record<string,number>,price:number,desc:string};
export function gearQuality(price:number){return price<500?1:price<2000?2:price<5000?3:price<10000?4:price<20000?5:price<35000?6:7}
