export const playerTier=(s:Game):number=>{const rk=s.jobsRank?.[s.job]||0;const base=jobs[s.job].attrStep?1+Math.floor(rk/10):1+Math.floor(rk/2);return Math.max(1,Math.min(10,base+Math.floor(age(s)/60)));}
