export function inherit(s:Game):Game|null{const child=s.children.find(c=>(s.day-c.born)/360>=adultAge(s.draft.race));if(!child||(!s.dead&&!s.retired))return null;const n=createGame({...s.draft,name:child.name,age:'成年 · 适龄'},s.mode);n.day=s.day;n.ageStart=Math.floor((s.day-child.born)/360)-Math.floor(s.day/360);n.cash=s.cash;n.debt=s.debt;n.debtDue=s.debtDue;n.estates=s.estates?structuredClone(s.estates):[];n.fief=s.fief?structuredClone(s.fief):null;n.region=s.region;n.known=[...s.known];n.fame=s.fame.map(f=>Math.round(f*.35));n.log=[...s.log];n.generation=s.generation+1;n.seed=s.seed;entry(n,'新的执笔人',`${child.name}接过家中的账册。资产、债务与世界历史仍在，技艺需要自己重新学习。`,['第'+n.generation+'代']);return n;}
export function parseCommand(text:string):[string,string]{const t=text.trim().replace(/[【】]/g,'');const panels=['属性','背包','技能','关系','任务','地图','势力','领地','日志','装备','魔法','家族','存档','规则','职业','市场','托管'];if(panels.includes(t))return ['panel',t];const direct:Record<string,string>={工作:'work',休息:'rest',探索:'explore',治疗:'heal',晋升:'promote',一年:'year',快进一年:'year',领取委托:'quest',交付委托:'deliver',借款:'borrow',还款:'repay',施法:'cast',返回:'return'};if(direct[t])return [direct[t],''];if(t.startsWith('训练')&&skillNames.includes(t.slice(2).trim()))return ['train',t.slice(2).trim()];if(t.startsWith('旅行')&&regions.some(r=>r.name===t.slice(2).trim()))return ['travel',String(regions.findIndex(r=>r.name===t.slice(2).trim()))];return ['unknown',''];}
export function validSave(v:unknown):v is Game{if(!v||typeof v!=='object')return false;const s=v as Game;const h=s.hosting;const validHosting=h===undefined||!!h&&['work','explore'].includes(h.action)&&['adventure','balanced','cautious'].includes(h.temperament)&&[h.staminaBelow,h.hpBelow,h.staminaRecoverTo??null,h.hpRecoverTo??null].every(x=>x===null||Number.isInteger(x)&&x>=0&&x<=100)&&(h.resting===undefined||typeof h.resting==='boolean')&&(h.forcedWork===undefined||typeof h.forcedWork==='boolean')&&(h.steps===undefined||Number.isInteger(h.steps)&&h.steps>=1&&h.steps<=5000)&&(h.targetDays===undefined||Number.isInteger(h.targetDays)&&h.targetDays>=7&&h.targetDays<=36000)&&typeof h.active==='boolean'&&Number.isInteger(h.completed)&&h.completed>=0&&typeof h.reason==='string';return validHosting&&(s.aiGoal===undefined||validLifeGoal(s.aiGoal))&&s.version===1&&typeof s.id==='string'&&!!s.draft&&typeof s.draft.name==='string'&&steps.every(x=>typeof s.draft[x.key]==='string')&&Number.isInteger(s.day)&&s.day>=0&&s.day<3600000&&Number.isInteger(s.region)&&s.region>=0&&s.region<6&&Number.isInteger(s.job)&&!!jobs[s.job]&&[s.cash,s.debt,s.hp,s.stamina,s.spirit,s.mana,s.maxMana,s.hunger,s.injury,s.seed,s.turn,s.ageStart,s.rank,s.generation,s.debtDue,s.crime].every(Number.isFinite)&&s.cash>=0&&s.debt>=0&&s.hp>=0&&s.hp<=1000&&s.stamina>=0&&s.stamina<=1000&&s.spirit>=0&&s.spirit<=1000&&s.mana>=0&&s.mana<=1000&&s.rank>=0&&s.rank<=100&&(s.jobsRank===undefined||Array.isArray(s.jobsRank)&&s.jobsRank.length===jobs.length&&s.jobsRank.every(x=>Number.isInteger(x)&&x>=0&&x<=100))&&!!s.attributes&&attrNames.every(k=>Number.isFinite(s.attributes[k]))&&!!s.skills&&skillNames.every(k=>Number.isFinite(s.skills[k])&&s.skills[k]>=0&&s.skills[k]<=120)&&Array.isArray(s.log)&&s.log.every(e=>typeof e.title==='string'&&typeof e.text==='string'&&Array.isArray(e.changes)&&e.changes.every(c=>typeof c==='string')&&Number.isFinite(e.day))&&Array.isArray(s.items)&&s.items.every(i=>typeof i.name==='string'&&typeof i.slot==='string'&&Number.isInteger(i.count)&&i.count>0&&Number.isFinite(i.weight)&&i.weight>=0&&Number.isFinite(i.durability))&&Array.isArray(s.npcs)&&s.npcs.every(n=>typeof n.id==='string'&&typeof n.name==='string'&&[n.age,n.trust,n.affinity,n.last].every(Number.isFinite))&&Array.isArray(s.quests)&&s.quests.every(q=>typeof q.title==='string'&&typeof q.status==='string'&&(q.skill===''||skillNames.includes(q.skill))&&[q.id,q.need,q.reward,q.due].every(Number.isFinite))&&Array.isArray(s.children)&&s.children.every(c=>typeof c.name==='string'&&Number.isFinite(c.born))&&Array.isArray(s.fame)&&s.fame.length===6&&s.fame.every(Number.isFinite)&&Array.isArray(s.known)&&s.known.every(i=>Number.isInteger(i)&&i>=0&&i<6)&&!!s.seen&&typeof s.seen==='object'&&(s.event===null||events.some(e=>e.id===s.event))&&(s.estates===undefined&&(s.estate===null||s.estate===undefined||typeof s.estate.name==='string'&&[s.estate.level,s.estate.condition,s.estate.workers,s.estate.revenue].every(Number.isFinite))||Array.isArray(s.estates)&&s.estates.every(e=>typeof e.name==='string'&&typeof e.type==='string'&&typeof e.cityId==='string'&&typeof e.streetId==='string'&&Number.isInteger(e.level)&&e.level>=1&&e.level<=10&&[e.condition,e.workers,e.revenue].every(Number.isFinite)))&&(s.fief===undefined||s.fief===null||typeof s.fief.name==='string'&&Number.isInteger(s.fief.level)&&s.fief.level>=1&&s.fief.level<=3&&[s.fief.pop,s.fief.tax,s.fief.garrison,s.fief.loyalty,s.fief.condition].every(Number.isFinite)&&Array.isArray(s.fief.officers)&&(s.fief.buildings===undefined||typeof s.fief.buildings==='object'&&!Array.isArray(s.fief.buildings)))&&(s.city===undefined||s.city===null||typeof s.city.name==='string'&&Number.isInteger(s.city.level)&&s.city.level>=1&&s.city.level<=5&&[s.city.pop,s.city.prosperity,s.city.tax,s.city.garrison,s.city.loyalty,s.city.condition].every(Number.isFinite)&&Array.isArray(s.city.officers)&&Array.isArray(s.city.streets)&&Array.isArray(s.city.notable)&&(s.city.taxRate===undefined||['low','med','high'].includes(s.city.taxRate))&&(s.city.buildings===undefined||typeof s.city.buildings==='object'&&!Array.isArray(s.city.buildings)))&&typeof s.mode==='string'&&typeof s.dead==='boolean'&&typeof s.retired==='boolean'&&(s.equip===undefined||!!s.equip&&typeof s.equip==='object')&&(s.battle===undefined||s.battle===null||typeof s.battle==='object'&&['dungeonId','hp','maxHp','stage','turn'].every(k=>typeof (s.battle as any)[k]==='number'||typeof (s.battle as any)[k]==='string')&&Array.isArray(s.battle.log)&&typeof s.battle.done==='boolean'&&typeof s.battle.won==='boolean')&&(s.fate===undefined||s.fate===null||typeof s.fate==='object'&&['hp','maxHp','atk','def','turn'].every(k=>typeof (s.fate as any)[k]==='number')&&Array.isArray(s.fate.log)&&typeof s.fate.done==='boolean'&&typeof s.fate.won==='boolean')&&(s.fateDone===undefined||typeof s.fateDone==='boolean')&&(s.clearedDungeons===undefined||Array.isArray(s.clearedDungeons)&&s.clearedDungeons.every(x=>dungeons.some(d=>d.id===x)))&&(s.market===undefined||s.market===null||Number.isInteger(s.market.day)&&Array.isArray(s.market.list)&&s.market.list.every((m:any)=>typeof m.name==='string'&&Number.isInteger(m.quality)&&m.quality>=1&&m.quality<=7&&Number.isFinite(m.price)));}
export function normalizeSave(v:any):any{if(!v||typeof v!=='object'||Array.isArray(v))return v;if(!Array.isArray(v.jobsRank)){const rk=Number.isFinite(v.rank)?v.rank:0;v.jobsRank=jobs.map((_,i)=>i===v.job?rk:0);}while(v.jobsRank.length<jobs.length)v.jobsRank.push(0);v.jobsRank=v.jobsRank.map((x:number,i:number)=>{if(i>=8&&x>0&&x<=4)return [0,10,30,60,100][x]||x;return x});v.rank=v.jobsRank[v.job]||0;if(!Array.isArray(v.jobExp))v.jobExp=jobs.map(()=>0);while(v.jobExp.length<jobs.length)v.jobExp.push(0);if(v.skills&&typeof v.skills==='object')for(const k of skillNames)if(!Number.isFinite(v.skills[k]))v.skills[k]=0;if(!Array.isArray(v.estates)){v.estates=[];if(v.estate){const o=v.estate;const rc=world[Math.max(0,v.region||0)];const tc=rc?rc.cities.find(c=>c.name===rc.town)||rc.cities[0]:null;v.estates.push({id:'e0',name:o.name,type:'工坊',cityId:tc?tc.id:'',streetId:tc&&tc.streets[0]?tc.streets[0].name:'',level:o.level||1,condition:o.condition,workers:o.workers,revenue:o.revenue});}v.estate=null;}else{const rc=world[Math.max(0,v.region||0)];const tc=rc?rc.cities.find(c=>c.name===rc.town)||rc.cities[0]:null;v.estates.forEach((e:any)=>{if(!e.cityId&&tc){e.cityId=tc.id;e.streetId=e.streetId||(tc.streets[0]?tc.streets[0].name:'')}});}if(!v.equip||typeof v.equip!=='object')v.equip={};if(!v.storyFlags||typeof v.storyFlags!=='object'||Array.isArray(v.storyFlags))v.storyFlags={};if(!v.battle||typeof v.battle!=='object')v.battle=null;if(!v.fate||typeof v.fate!=='object')v.fate=null;else if(v.fate.done&&!v.fate.won&&!v.dead)v.fate=null;if(!Array.isArray(v.clearedDungeons))v.clearedDungeons=[];if(v.fateDone===undefined)v.fateDone=!!v.fate;if(!v.market||typeof v.market!=='object'||!Number.isInteger(v.market.day)||!Array.isArray(v.market.list))v.market={day:v.day||0,list:refreshMarketList(v)};if(v.fief&&typeof v.fief==='object'&&(v.fief.buildings===undefined||typeof v.fief.buildings!=='object'))v.fief.buildings={};if(v.city&&typeof v.city==='object'){if(v.city.buildings===undefined||typeof v.city.buildings!=='object')v.city.buildings={};if(v.city.officers===undefined||!Array.isArray(v.city.officers))v.city.officers=[];if(v.city.streets===undefined||!Array.isArray(v.city.streets))v.city.streets=[];if(v.city.notable===undefined||!Array.isArray(v.city.notable))v.city.notable=[];if(v.city.taxRate===undefined)v.city.taxRate='med';}return v;}
